PDF_TOOLS=[
('word-to-pdf','Word to PDF','تحويل Word إلى PDF','Preview a DOCX document and download it as a PDF.','عاين مستند DOCX وحمّله بصيغة PDF.','pdf','PDF','blue'),
('images-to-pdf','Images to PDF','تحويل الصور إلى PDF','Turn your photos into one neatly arranged PDF.','حوّل صورك إلى ملف PDF واحد مرتب.','image','PDF','teal'),
('pdf-splitter','Extract PDF Pages','استخراج صفحات PDF','Choose the pages you need and save a new PDF.','اختر الصفحات التي تحتاجها واحفظها في PDF جديد.','pdf','PDF','violet'),
('pdf-remove-pages','Remove PDF Pages','حذف صفحات PDF','Remove unwanted pages and keep the rest.','احذف الصفحات غير المطلوبة واحتفظ بالباقي.','pdf','PDF','red'),
('pdf-rotate','Rotate PDF','تدوير صفحات PDF','Fix sideways pages with a few simple clicks.','صحّح اتجاه الصفحات بسهولة.','resize','PDF','orange')]
PDF_SLUGS={t[0] for t in PDF_TOOLS}
def pdf_workspace(slug,ar):
 L=lambda en,an:an if ar else en
 word=slug=='word-to-pdf';images=slug=='images-to-pdf'
 accept='.docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document' if word else 'image/jpeg,image/png,image/webp' if images else '.pdf,application/pdf'
 upload=f'<label class="dropzone" id="pdf-drop"><span class="upload-icon">＋</span><strong>{L("Choose files or drop them here","اختر الملفات أو اسحبها هنا")}</strong><span>{L("DOCX only · Up to 15 MB", "DOCX فقط · حتى 15 ميغابايت") if word else L("JPEG, PNG, WebP · Up to 20 images, 50 MB total","JPEG وPNG وWebP · حتى 20 صورة و50 ميغابايت إجمالاً") if images else L("PDF · Up to 50 MB and 1,000 pages","PDF · حتى 50 ميغابايت و1,000 صفحة")}</span><input id="pdf-files" type="file" accept="{accept}" {"multiple" if images else ""}></label>'
 if word:
  return upload+f'<p class="conversion-note">{L("Supports .docx, not legacy .doc. Complex layouts may differ from Microsoft Word. The PDF is image-based: text is not selectable. Review the preview before downloading.","يدعم .docx وليس .doc القديم. قد يختلف التنسيق المعقد عن Microsoft Word. صفحات PDF صور، لذا لا يمكن تحديد النص. راجع المعاينة قبل التحميل.")}</p><iframe id="word-preview" class="word-preview" title="{L("Word document preview","معاينة مستند Word")}" sandbox="allow-scripts" src="/assets/word-frame.html" hidden></iframe><button class="primary" id="pdf-run" disabled>{L("Download PDF","تحميل PDF")}</button>'
 if images:
  return upload+f'<ol id="pdf-file-list" class="file-list"></ol><div class="two-cols"><label>{L("Page size","حجم الصفحة")}<select id="pdf-paper"><option value="a4">A4</option><option value="letter">{L("US Letter","Letter الأمريكي")}</option><option value="image">{L("Match image","مطابقة الصورة")}</option></select></label><label>{L("Orientation","الاتجاه")}<select id="pdf-orientation"><option value="portrait">{L("Portrait","عمودي")}</option><option value="landscape">{L("Landscape","أفقي")}</option></select></label></div><button class="primary" id="pdf-run" disabled>{L("Create & download PDF","إنشاء وتحميل PDF")}</button>'
  
 return upload+f'<p id="pdf-details" class="result-box"></p><div id="pdf-options" hidden><label>{L("Pages to remove" if slug=="pdf-remove-pages" else "Pages to rotate" if slug=="pdf-rotate" else "Pages to extract", "الصفحات المطلوب حذفها" if slug=="pdf-remove-pages" else "الصفحات المطلوب تدويرها" if slug=="pdf-rotate" else "الصفحات المطلوب استخراجها")}<input id="pdf-pages" type="text" placeholder="1, 3-5" dir="ltr" aria-describedby="range-help"></label><p id="range-help" class="muted">{L("Use page numbers and ranges, for example 1, 3-5. Extracted pages follow your chosen order. For rotation, leave blank to rotate all pages.","استخدم أرقام الصفحات أو نطاقات مثل 1, 3-5. تُرتّب الصفحات المستخرجة حسب إدخالك. للتدوير اترك الحقل فارغاً لتدوير الكل.")}</p>'+ (f'<label>{L("Clockwise rotation","التدوير باتجاه عقارب الساعة")}<select id="pdf-angle"><option value="90">90°</option><option value="180">180°</option><option value="270">270°</option></select></label>' if slug=='pdf-rotate' else '')+f'<button class="primary" id="pdf-run">{L("Download PDF","تحميل PDF")}</button></div>'
def pdf_help(slug,ar):
 L=lambda en,an:an if ar else en
 word=slug=='word-to-pdf';images=slug=='images-to-pdf'
 steps= [L('Choose a DOCX document. Legacy DOC files are not supported.','اختر مستند DOCX؛ ملفات DOC القديمة غير مدعومة.'),L('Wait for the document preview, then check every page.','انتظر المعاينة ثم راجع جميع الصفحات.'),L('Download the PDF. Text is stored as page images.','حمّل ملف PDF. يُحفظ النص كصور للصفحات.')] if word else [L('Choose your images.','اختر صورك.'),L('Arrange the image order and choose the page size.','رتّب الصور واختر حجم الصفحة.'),L('Create and download your PDF.','أنشئ ملف PDF وحمّله.')] if images else [L('Choose an unencrypted PDF.','اختر ملف PDF غير مشفّر.'),L('Enter page numbers or ranges, such as 1, 3-5.','أدخل أرقام الصفحات أو النطاقات مثل 1, 3-5.'),L('Download and review your new PDF. The original stays unchanged.','حمّل ملفك الجديد وراجعه. يبقى الأصل دون تغيير.')]
 answer=L('Conversion happens on your device. DOCX layout is rendered in an isolated preview and exported as page images. Fonts, equations, floating objects, complex tables, headers and page breaks may differ. Use Microsoft Word export for exact Office fidelity. Maximum 30 rendered pages and 100 MB expanded DOCX content.','يتم التحويل على جهازك. يُعرض DOCX في معاينة معزولة ثم يُصدّر كصور للصفحات. قد تختلف الخطوط والمعادلات والعناصر العائمة والجداول المعقدة والترويسات وفواصل الصفحات. استخدم التصدير من Microsoft Word عند الحاجة لتطابق دقيق. الحد الأقصى 30 صفحة معروضة و100 ميغابايت بعد فك الضغط.') if word else L('Each image becomes one page. Images fit within the selected paper size without cropping; matching image size uses its pixel dimensions at 96 pixels per inch. Transparent backgrounds become white.','تصبح كل صورة صفحة واحدة. تُلائم الصور حجم الورق دون قص؛ خيار مطابقة الصورة يستخدم أبعاد البكسل بمقياس 96 بكسلاً لكل بوصة. تصبح الخلفيات الشفافة بيضاء.') if images else L('This tool changes PDF pages locally. Password-protected or damaged files are rejected. Interactive forms, bookmarks and digital signatures may not be preserved. Review your output.','تُعدّل الصفحات محلياً. الملفات المحمية أو التالفة تُرفض. قد لا تُحفظ النماذج التفاعلية والإشارات المرجعية والتوقيعات الرقمية. راجع النتيجة.')
 return '<div class="help-grid"><section><h2>'+L('How to use this tool','كيفية الاستخدام')+'</h2><ol class="steps">'+''.join('<li>'+s+'</li>' for s in steps)+'</ol></section><section><h2>'+L('Good to know','معلومات مهمة')+'</h2><details open><summary>'+L('What should I expect?','ما الذي يجب معرفته؟')+'</summary><p>'+answer+'</p></details><details><summary>'+L('Are my files uploaded?','هل تُرفع ملفاتي؟')+'</summary><p>'+L('No. Files stay in your browser. No file content is sent to a server.','لا. تبقى الملفات في متصفحك ولا يُرسل محتواها إلى خادم.')+'</p></details></section></div>'
